import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import time
import struct

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, sku TEXT,
        quantity INTEGER, warehouse TEXT, unit_cost REAL)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY, owner TEXT, scope TEXT, created_at TEXT)''')
    db.execute('''INSERT OR IGNORE INTO products VALUES
        (1,'Widget A','WA-001',500,'east',2.50),
        (2,'Widget B','WB-002',300,'west',3.75),
        (3,'Gadget C','GC-003',150,'east',12.00)''')
    db.commit()
    db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    if not key:
        return False
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT scope FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    return row is not None

@app.route('/api/v2/inventory/search', methods=['GET'])
def search_inventory():
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

    warehouse = request.args.get('warehouse', '')
    sku_prefix = request.args.get('sku_prefix', '')
    min_qty = request.args.get('min_qty', '0')
    sort_col = request.args.get('sort', 'name')

    # Validate sort column against allowlist
    allowed_sorts = ['name', 'sku', 'quantity', 'unit_cost', 'warehouse']
    if sort_col not in allowed_sorts:
        sort_col = 'name'

    # Build query with filters
    conditions = []
    params = []

    if warehouse:
        conditions.append('warehouse = ?')
        params.append(warehouse)

    if sku_prefix:
        conditions.append('sku LIKE ?')
        params.append(sku_prefix + '%')

    where_clause = ' WHERE ' + ' AND '.join(conditions) if conditions else ''

    # min_qty used directly in HAVING clause for aggregate query
    query = f"""SELECT warehouse, COUNT(*) as item_count, 
               SUM(quantity) as total_qty, AVG(unit_cost) as avg_cost
               FROM products{where_clause}
               GROUP BY warehouse
               HAVING total_qty >= {min_qty}
               ORDER BY {sort_col}"""

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/inventory/item/<int:item_id>', methods=['GET'])
def get_item(item_id):
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401
    db = get_db()
    row = db.execute('SELECT * FROM products WHERE id = ?', (item_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/v2/inventory/restock', methods=['POST'])
def restock():
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401
    data = request.get_json()
    if not data or 'sku' not in data or 'add_qty' not in data:
        return jsonify({'error': 'missing fields'}), 400
    db = get_db()
    db.execute('UPDATE products SET quantity = quantity + ? WHERE sku = ?',
               (int(data['add_qty']), data['sku']))
    db.commit()
    return jsonify({'status': 'updated'})

@app.route('/healthz')
def health():
    return jsonify({'status': 'ok', 'ts': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
